-- Shared aggregate SQL: executes unchanged in SQLite fixtures and BigQuery.
-- Input is journey_users generated by trial_journey.sql. No UID is returned.
-- query: funnel
WITH stages AS (
  SELECT 1 AS stage_order, 'registration' AS stage, '登録' AS label, COUNT(*) AS users FROM journey_users
  UNION ALL SELECT 2,'trial','21日trial',COALESCE(SUM(trial_started),0) FROM journey_users
  UNION ALL SELECT 3,'a1','A1 AI相談成功',COALESCE(SUM(CASE WHEN funnel_depth>=3 THEN 1 ELSE 0 END),0) FROM journey_users
  UNION ALL SELECT 4,'a2','A2 初回記録',COALESCE(SUM(CASE WHEN funnel_depth>=4 THEN 1 ELSE 0 END),0) FROM journey_users
  UNION ALL SELECT 5,'a3_ready','A3 分析ready',COALESCE(SUM(CASE WHEN funnel_depth>=5 THEN 1 ELSE 0 END),0) FROM journey_users
  UNION ALL SELECT 6,'a3_generated','A3 レポート生成',COALESCE(SUM(CASE WHEN funnel_depth>=6 THEN 1 ELSE 0 END),0) FROM journey_users
  UNION ALL SELECT 7,'a3_viewed','A3 実際の閲覧',COALESCE(SUM(CASE WHEN funnel_depth>=7 THEN 1 ELSE 0 END),0) FROM journey_users
  UNION ALL SELECT 8,'paid','有料契約',COALESCE(SUM(CASE WHEN funnel_depth>=8 THEN 1 ELSE 0 END),0) FROM journey_users
)
SELECT *, (SELECT COUNT(*) FROM journey_users) AS eligible_users,
  1.0*users/NULLIF((SELECT COUNT(*) FROM journey_users),0) AS rate
FROM stages ORDER BY stage_order;
-- query: retention
WITH days AS (
 SELECT 1 AS day,COALESCE(SUM(d1_eligible),0) AS eligible_users,COALESCE(SUM(CASE WHEN d1_eligible=1 THEN d1_retained ELSE 0 END),0) AS retained_users FROM journey_users
 UNION ALL SELECT 7,COALESCE(SUM(d7_eligible),0),COALESCE(SUM(CASE WHEN d7_eligible=1 THEN d7_retained ELSE 0 END),0) FROM journey_users
 UNION ALL SELECT 14,COALESCE(SUM(d14_eligible),0),COALESCE(SUM(CASE WHEN d14_eligible=1 THEN d14_retained ELSE 0 END),0) FROM journey_users
 UNION ALL SELECT 21,COALESCE(SUM(d21_eligible),0),COALESCE(SUM(CASE WHEN d21_eligible=1 THEN d21_retained ELSE 0 END),0) FROM journey_users
)
SELECT *,1.0*retained_users/NULLIF(eligible_users,0) AS rate FROM days ORDER BY day;
-- query: conversion_cohorts
SELECT cohort_month AS cohort,COUNT(*) AS trial_starts,COALESCE(SUM(conversion_eligible),0) AS eligible_trials,
 COALESCE(SUM(CASE WHEN conversion_eligible=1 THEN converted ELSE 0 END),0) AS converted_trials,
 COALESCE(SUM(CASE WHEN conversion_eligible=0 THEN 1 ELSE 0 END),0) AS immature_trials,
 1.0*SUM(CASE WHEN conversion_eligible=1 THEN converted ELSE 0 END)/NULLIF(SUM(conversion_eligible),0) AS rate
FROM journey_users WHERE trial_started=1 GROUP BY cohort_month ORDER BY cohort_month;
-- query: a3
SELECT COUNT(*) AS registered_users,COALESCE(SUM(trial_started),0) AS trial_starts,
 COALESCE(SUM(ready),0) AS ready,COALESCE(SUM(body_ready),0) AS body_ready,COALESCE(SUM(activity_ready),0) AS activity_ready,
 COALESCE(SUM(generated),0) AS generated,COALESCE(SUM(viewed),0) AS viewed,
 COALESCE(SUM(paywall),0) AS paywall,COALESCE(SUM(checkout),0) AS checkout,COALESCE(SUM(paid),0) AS paid,
 COALESCE(SUM(cancel_scheduled),0) AS cancel_scheduled,COALESCE(SUM(ended),0) AS ended,
 1.0*SUM(ready)/NULLIF(SUM(trial_started),0) AS ready_rate,
 1.0*SUM(generated)/NULLIF(SUM(trial_started),0) AS generated_rate,
 1.0*SUM(viewed)/NULLIF(SUM(trial_started),0) AS viewed_rate
FROM journey_users;
-- query: landmark_segments
SELECT landmark_segment AS segment,COUNT(*) AS eligible_trials,COALESCE(SUM(landmark_retained),0) AS retained_trials,
 1.0*SUM(landmark_retained)/NULLIF(COUNT(*),0) AS retention_rate,
 COALESCE(SUM(landmark_conversion_eligible),0) AS conversion_eligible_trials,
 COALESCE(SUM(CASE WHEN landmark_conversion_eligible=1 THEN landmark_converted ELSE 0 END),0) AS converted_trials,
 1.0*SUM(CASE WHEN landmark_conversion_eligible=1 THEN landmark_converted ELSE 0 END)/NULLIF(SUM(landmark_conversion_eligible),0) AS conversion_rate
FROM journey_users WHERE landmark_eligible=1 GROUP BY landmark_segment ORDER BY landmark_segment;
